<script setup lang="ts">
import { computed, ref } from 'vue';
import { Clock3, RefreshCw } from 'lucide-vue-next';
import type { ResearchModel } from '../../composables/useResearch';
import ConfirmDialog from '../ConfirmDialog.vue';
import { percent, time } from './format';
const props = defineProps<{ model: ResearchModel }>();
const selectedId = ref('');
const shadowConsent = ref(false);
const records = computed(() => props.model.ledger?.records || []);
const selected = computed(() => records.value.find(r => r.id === selectedId.value) || records.value[0]);
const shadow = computed(() => props.model.ledger?.shadows.find(s => s.recordId === selected.value?.id));
async function register() { if (!selected.value || !props.model.api.registerResearchShadow) return; const recordId = selected.value.id; await props.model.mutate(() => props.model.api.registerResearchShadow!({ recordId, horizonMs: 24 * 3600_000, acknowledgeIndicative: true })); if (!props.model.actionError) shadowConsent.value = false; }
</script>
<template>
  <main class="review-page" aria-labelledby="review-heading"><div class="workspace-heading"><div><p class="eyebrow">冻结判断 · 追加后续证据</p><h1 id="review-heading">研究复盘</h1></div><button class="button subtle" @click="model.loadLedger"><RefreshCw :size="15"/>刷新记录</button></div>
    <div class="review-summary"><div><span>研究记录</span><strong>{{ model.ledger ? records.length : '—' }}</strong></div><div><span>已完成价格观察</span><strong>{{ model.ledger ? model.ledger.shadows.filter(s => s.status === 'complete').length : '—' }}</strong></div><div><span>净收益 / 胜率</span><strong>—</strong><small>成本与有效执行样本不足</small></div></div>
    <div v-if="!records.length" class="research-empty review-empty"><Clock3 :size="32"/><h2>让判断留下可复核的记录</h2><p>运行一次 AI 查证后，原始判断与证据会保存在本机。</p><p>没有样本时，不生成胜率、收益或盈利结论。</p></div>
    <div v-else class="review-layout"><section class="review-list" aria-label="历史研究记录"><button v-for="record in records" :key="record.id" class="review-row" :class="{ selected: selected?.id === record.id }" :aria-pressed="selected?.id === record.id" @click="selectedId = record.id"><span><strong>{{ record.judgment.symbol }}</strong><small>{{ new Date(record.recordedAt).toLocaleDateString('zh-CN') }} {{ time(record.recordedAt) }}</small></span><span>{{ {hypothesis:'有条件假设',abstain:'暂不判断',failed:'查证失败'}[record.judgment.decision] }}</span><small>{{ record.observations.length }} 条后续</small></button></section><aside v-if="selected" class="review-detail"><h2>{{ selected.judgment.symbol }}</h2><span class="eyebrow">{{ selected.judgment.model || '模型未知' }} · {{ time(selected.judgment.decidedAt) }}</span><p class="frozen-summary">{{ selected.judgment.summary }}</p><section class="evidence-section"><h3>原始条件与失效条件</h3><ul class="evidence-bullets"><li v-for="condition in selected.judgment.conditions" :key="condition">{{ condition }}</li><li v-for="condition in selected.judgment.invalidation" :key="condition">失效：{{ condition }}</li></ul><p v-if="!selected.judgment.conditions.length && !selected.judgment.invalidation.length" class="muted">未形成有效条件。</p></section><section class="evidence-section"><h3>后续观察</h3><ol v-if="selected.observations.length" class="review-timeline"><li v-for="observation in selected.observations" :key="observation.id"><time>{{ time(observation.at) }}</time><span>{{ observation.message }}</span></li></ol><p v-else class="muted">暂无后续证据。</p></section><section class="evidence-section"><h3>24 小时价格观察</h3><template v-if="shadow"><p>{{ {'awaiting-entry':'等待下一次新鲜成交价',observing:'观察中',complete:'价格观察完成',censored:'观察无效 / 不完整'}[shadow.status] }}</p><dl class="evidence-values"><div><dt>方向价格变化 · 毛值</dt><dd>{{ percent(shadow.grossPriceReturnPercent) }}</dd></div><div><dt>同期买入持有 · 价格</dt><dd>{{ percent(shadow.buyHoldPriceReturnPercent) }}</dd></div><div><dt>净收益</dt><dd>—</dd></div></dl><p class="helper">{{ shadow.reason || '费用、滑点与资金费未知；价格观察不等于回测或真实交易。' }}</p></template><template v-else><p class="muted">从下一次新鲜报价开始，记录固定期限内的价格变化。</p><button class="button subtle" :disabled="selected.judgment.decision !== 'hypothesis' || selected.judgment.direction === 'neutral' || !model.api.registerResearchShadow" @click="shadowConsent = true">创建价格观察</button></template></section><details class="evidence-section source-details"><summary>冻结证据 · {{ selected.judgment.facts.length }} 条</summary><p v-for="fact in selected.judgment.facts" :key="fact.id">{{ fact.label }} · {{ fact.value }} {{ fact.unit }} · {{ time(fact.observedAt) }}</p><p v-for="gap in selected.judgment.gaps" :key="gap" class="helper">{{ gap }}</p></details></aside></div>
    <p v-if="model.actionError" class="research-error" role="alert">{{ model.actionError }}</p><footer class="workspace-bottomline">原判断不回写；后续变化追加记录 · 不以投资收益证明产品安全</footer>
    <ConfirmDialog v-if="shadowConsent" title="创建 24 小时价格观察？" confirm-label="确认创建价格观察" :busy="model.actionBusy" @close="shadowConsent = false" @confirm="register"><p>使用下一次新鲜成交价作为参考起点，24 小时后取新的公开报价。不会下单。</p><p>费用、滑点与资金费均未知，不能据此计算净收益、胜率或证明盈利能力。</p></ConfirmDialog>
  </main>
</template>
